const items = $input.all();
const CHECK_TYPES = ["safety", "narrative", "editorial", "cultural"];

const results = {};
for (const item of items) {
  const json = item.json;
  if (json.check_type) {
    results[json.check_type] = json;
  }
}

// Detect checks that never produced a valid result (missing branch or JSON parse failure)
const missingChecks = CHECK_TYPES.filter(t => !results[t]);
const parseErrorChecks = CHECK_TYPES.filter(t => results[t]?.parse_error === true);

const technicalFailure = missingChecks.length > 0 || parseErrorChecks.length > 0;

// Content failure = a check ran successfully but flagged the story as non-compliant
const contentFailedChecks = CHECK_TYPES.filter(
  t => results[t] && results[t].parse_error === false && results[t].passed === false
);

const allPassed = !technicalFailure && CHECK_TYPES.every(t => results[t]?.passed === true);

// Global score = average of the 4 individual scores that are valid numbers.
// A missing/invalid score on one check does not block the others from contributing.
const validScores = CHECK_TYPES
  .map(t => results[t]?.score)
  .filter(s => typeof s === 'number');

const globalScore = validScores.length > 0
  ? Math.round((validScores.reduce((a, b) => a + b, 0) / validScores.length) * 10) / 10
  : null;

let globalReason = "ok";
if (technicalFailure) {
  const parts = [];
  if (missingChecks.length > 0) parts.push("missing result(s) from: " + missingChecks.join(", "));
  if (parseErrorChecks.length > 0) parts.push("parse error(s) on: " + parseErrorChecks.join(", "));
  globalReason = "technical failure - " + parts.join("; ");
} else if (contentFailedChecks.length > 0) {
  globalReason = "content failed on: " + contentFailedChecks.join(", ");
}

return {
  json: {
    story_id: items.find(i => i.json.story_id)?.json.story_id || null,
    approved: !!allPassed,
    technical_failure: technicalFailure,
    global_score: globalScore,
    safety: results.safety || null,
    narrative: results.narrative || null,
    editorial: results.editorial || null,
    cultural: results.cultural || null,
    global_reason: globalReason
  }
};

const item = $input.first().json;

const generateToken = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let token = '';
  for (let i = 0; i < 32; i++) {
    token += chars[Math.floor(Math.random() * chars.length)];
  }
  return token;
};

return {
  ...item,
  token_approve: generateToken(),
  token_reject: generateToken(),
};

const agg = $('Aggregate Results').first().json;
const story = $('Loop Over Items').first().json;
const locale = $('Get locale_profile').first().json.locale_profile || {};

const staticData = $getWorkflowStaticData('global');
if (!staticData.reports) staticData.reports = [];

const tc = locale.target_culture;
const targetCulture = typeof tc === 'object' ? (tc?.country || '') : (tc || '');

staticData.reports.push({
  story_id: agg.story_id || story.story_id,
  title: story.title || '',
  target_culture: targetCulture,
  approved: agg.approved,
  technical_failure: agg.technical_failure,
  global_reason: agg.global_reason,
  safety_passed: agg.safety?.passed ?? null,
  safety_reason: agg.safety?.reason || '',
  narrative_passed: agg.narrative?.passed ?? null,
  narrative_reason: agg.narrative?.reason || '',
  editorial_passed: agg.editorial?.passed ?? null,
  editorial_reason: agg.editorial?.reason || '',
  cultural_passed: agg.cultural?.passed ?? null,
  cultural_reason: agg.cultural?.reason || ''
});

// pass the items through so the loop continues normally
return $input.all();

