return {
  parse_error: false,
  auto_fixed: usedFix,
  check_type: promptData.check_type,
  story_id: promptData.story_id,
  passed: result.passed,
  score: score,
  reason: result.reason || ""
};

const response = $input.item.json;
const promptData = $('Build Cultural Prompt1').item.json;

let rawText = "";
const finishReason = response.choices?.[0]?.finish_reason;

try {
  rawText = response.choices[0].message.content;
} catch (e) {
  return {
    parse_error: true,
    error_message: "No content in LLM response (exception): " + e.message,
    raw_response: JSON.stringify(response),
    check_type: promptData.check_type,
    story_id: promptData.story_id
  };
}

if (typeof rawText !== 'string' || rawText.trim() === '') {
  return {
    parse_error: true,
    error_message: "LLM response content is empty or not a string",
    raw_response: JSON.stringify(response),
    check_type: promptData.check_type,
    story_id: promptData.story_id
  };
}

if (finishReason === 'length') {
  return {
    parse_error: true,
    error_message: "LLM response was truncated (finish_reason=length). Consider raising max_tokens or reasoning_effort.",
    raw_response: rawText.slice(-300),
    check_type: promptData.check_type,
    story_id: promptData.story_id
  };
}

const cleanedText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// Attempts to fix common JSON formatting errors produced by the LLM
function tryFixCommonJsonErrors(text) {
  let fixed = text;
  fixed = fixed.replace(/\]\]/g, ']');             // accidental "]]" -> "]"
  fixed = fixed.replace(/\}\}(\s*,\s*")/g, '}$1');  // accidental "}}" -> "}"
  fixed = fixed.replace(/\\"\]/g, '"]');            // misplaced escaped quote before "]"
  fixed = fixed.replace(/,(\s*[\}\]])/g, '$1');     // trailing comma
  return fixed;
}

let result;
let usedFix = false;

try {
  result = JSON.parse(cleanedText);
} catch (firstError) {
  try {
    const fixedText = tryFixCommonJsonErrors(cleanedText);
    result = JSON.parse(fixedText);
    usedFix = true;
  } catch (secondError) {
    return {
      parse_error: true,
      error_message: "JSON parse failed even after auto-fix: " + secondError.message + " (original error: " + firstError.message + ")",
      raw_response: cleanedText,
      check_type: promptData.check_type,
      story_id: promptData.story_id
    };
  }
}

// Enforce that the expected 'passed' boolean field is present
if (typeof result.passed !== 'boolean') {
  return {
    parse_error: true,
    error_message: "Parsed JSON is missing a boolean 'passed' field",
    raw_response: cleanedText,
    check_type: promptData.check_type,
    story_id: promptData.story_id
  };
}

// Validate 'score' — invalid or missing score does NOT trigger a parse_error,
// it just comes through as null so the report can show "N/A" instead of blocking a retry.
let score = Number(result.score);
if (!Number.isInteger(score) || score < 1 || score > 5) {
  score = null;
}

return {
  parse_error: false,
  auto_fixed: usedFix,
  check_type: promptData.check_type,
  story_id: promptData.story_id,
  passed: result.passed,
  score: score,
  reason: result.reason || ""
};

const story = $('Loop Over Items1').item.json;
