const NOT_A_CHARACTER = /^(the\s+)?(ending|end|moral|lesson|resolution|story|relationship|bond)\b|moral|lesson|must|should|never|always|one should|dangerous|unattainable/i;

const protectedNames = (blueprint.protected_elements || [])
  .map(x => String(x || '').trim())
  .filter(x =>
    x && x.length <= 40 && x.split(/\s+/).length <= 6 &&
    !/[.;:!?]/.test(x) && !NOT_A_CHARACTER.test(x)
  )
  .map(x => x.replace(/^the\s+/i, ''));

if (!story.adapted_text) throw new Error('adapted_text vide pour ' + story.story_id);
if (protectedNames.length === 0) {
  throw new Error('Aucun nom protégé détecté pour ' + story.story_id +
