}

return {
  story_id: story.story_id,
  target_culture: story.target_culture,
  locale_profile_id: story.locale_profile_id,
  system: 'artifacts',

  // SAFETY / tous les checks : texte brut complet
  story_text: 'TITLE: ' + story.title + '\n\n' + story.adapted_text,

  // NARRATIVE + EDITORIAL
  blueprint_summary: JSON.stringify({
