    core_moral: blueprint.core_moral,
    initial_conflict: blueprint.initial_state?.initial_conflict,
    conflicts: (blueprint.conflicts || []).map(c => ({ type: c.type, description: c.description, resolution: c.resolution })),
    key_events: (blueprint.key_events || [])
      .filter(e => e.is_protected)
      .map(e => ({ id: e.event_id, description: e.description }))
  }),

  // CULTURAL uniquement
  character_registry: JSON.stringify(protectedNames),

  // NARRATIVE uniquement
  character_roles: JSON.stringify(
    (bible.characters || []).map(c => ({ id: c.character_id, role: c.role }))
  ),

  // EDITORIAL
  bible_summary: JSON.stringify({
    characters: (bible.characters || []).map(c => ({
      id: c.character_id, role: c.role, traits: c.traits, protected_attributes: c.protected_attributes
    })),
    relationships: (bible.relationships || []).filter(r => r.is_protected).map(r => r.description),
    world_rules: (bible.world_rules || []).filter(r => r.is_protected).map(r => r.rule),
    continuity_constraints: bible.continuity_constraints || []
  }),

  // CULTURAL
  locale_summary: JSON.stringify({
    target_culture: story.target_culture,
    adaptation_principles: locale.adaptation_principles,
    setting: locale.setting,
    social_context: locale.social_context,
    cultural_elements: locale.cultural_elements,
    language_style: locale.language_style,
    preservation_rules: locale.preservation_rules,
    forbidden_adaptations: locale.forbidden_adaptations,
